// MCP Registry - Liste des services disponibles
const registry = {
  version: "1.0",
  updated_at: new Date().toISOString(),
  n8n: {
    host: "pi6.local",
    port: 5678,
    protocol: "http"
  },
  services: {
    gmail: {
      name: "Gmail MCP Server",
      webhook_url: "http://pi6.local:5678/webhook/mcp-gmail",
      description: "Gmail API operations with dynamic OAuth token",
      auth: {
        type: "oauth2_token",
        param: "access_token"
      },
      operations: {
        message: ["get", "getAll", "send", "reply", "delete", "markAsRead", "markAsUnread", "addLabels", "removeLabels"],
        label: ["getAll", "get", "create", "delete"],
        draft: ["create", "get", "getAll", "delete"],
        thread: ["getAll", "get", "reply", "addLabels", "removeLabels"]
      }
    }
  }
};

return { json: registry };
